        ["Минимум резервных версий KDBX"] = ("Мінімум резервних версій KDBX", "Minimum backup versions"),
        ["Минимальный срок хранения версий, дней"] = ("Мінімальний строк зберігання версій, днів", "Minimum version retention, days"),
        ["Компьютер · участник топологии"] = ("Комп’ютер · учасник топології", "Computer · topology member"),
        ["Выйти из KeyPassXC Cloud Sync?"] = ("Вийти з KeyPassXC Cloud Sync?", "Exit KeyPassXC Cloud Sync?"),
        ["Синхронизация остановится, приложение закроется. База KDBX, настройки и реквизиты останутся на месте. Для фоновой работы просто сверните окно в трей."] = ("Синхронізація зупиниться, застосунок закриється. База KDBX, налаштування й облікові дані залишаться. Для роботи у фоні згорніть вікно в трей.", "Synchronization will stop and the application will close. The KDBX database, settings and credentials will remain. Minimize to the tray to continue in the background."),
        ["Позже"] = ("Пізніше", "Later"),
        ["Напомнить через 24 часа"] = ("Нагадати через 24 години", "Remind in 24 hours"),
        ["Скачано"] = ("Завантажено", "Downloaded"),
