        ["Всё время"] = ("Весь час", "All time"),
        ["Компьютер «{0}» будет убран из архива и статистики после публикации топологии."] = ("Комп’ютер «{0}» буде прибрано з архіву та статистики після публікації топології.", "Computer “{0}” will be removed from the archive and statistics after the topology is published."),
        ["Имя и статистика исчезнут из приложения. Минимальный идентификатор останется для защиты от повторного подключения."] = ("Ім’я та статистика зникнуть із застосунку. Мінімальний ідентифікатор залишиться для захисту від повторного підключення.", "The name and statistics will disappear from the application. A minimal ID is retained to prevent reconnection."),
        ["Облако «{0}» будет убрано из архива и статистики после публикации топологии."] = ("Хмару «{0}» буде прибрано з архіву та статистики після публікації топології.", "Cloud “{0}” will be removed from the archive and statistics after the topology is published."),
        ["Статистика исчезнет из приложения без автоматического восстановления."] = ("Статистика зникне із застосунку без автоматичного відновлення.", "Statistics will disappear from the application and will not be restored automatically."),
        ["Облачные файлы и резервные копии физически не удаляются. Продолжить?"] = ("Хмарні файли та резервні копії фізично не видаляються. Продовжити?", "Cloud files and backups are not physically deleted. Continue?"),
        ["Запрос записан. Окончательное удаление произойдёт после публикации общей топологии в облаке. До этого архивная запись может оставаться видимой."] = ("Запит збережено. Остаточне видалення відбудеться після публікації спільної топології в хмарі. До цього архівний запис може залишатися видимим.", "Request saved. Permanent deletion will take effect after the shared topology is published to the cloud. The archived record may remain visible until then."),
        ["Удалить окончательно"] = ("Видалити остаточно", "Permanently delete"),
        ["Окончательно удалить компьютер"] = ("Остаточно видалити комп’ютер", "Permanently delete computer"),
        ["Окончательно удалить облако"] = ("Остаточно видалити хмару", "Permanently delete cloud"),
        ["Очистка запланирована"] = ("Очищення заплановано", "Cleanup queued"),
        ["Окончательное удаление"] = ("Остаточне видалення", "Permanent deletion"),
        ["Показывать удалённые"] = ("Показувати видалені", "Show removed"),
