        ["Выбор каталога"] = ("Вибір каталогу", "Folder selection"),
        ["Настройки сохранены. Запущена проверка облаков."] = ("Налаштування збережено. Почато перевірку хмар.", "Settings saved. Cloud check started."),
        ["Сохранено"] = ("Збережено", "Saved"),
        ["Настройки приняты. Синхронизация продолжится автоматически."] = ("Налаштування прийнято. Синхронізація продовжиться автоматично.", "Settings accepted. Synchronization will continue automatically."),
