        // Complete UI coverage: settings, dashboard, cloud dialogs and user-facing messages.
        ["Две независимые группы: общие параметры распространяются через топологию; локальные действуют только на этом компьютере."] = ("Дві незалежні групи: спільні параметри поширюються через топологію, локальні діють лише на цьому комп’ютері.", "Two independent groups: shared settings are distributed via the topology; local settings apply only to this computer."),
        ["Хранятся только на этом ПК. Не передаются другим компьютерам."] = ("Зберігаються лише на цьому ПК. Не передаються іншим комп’ютерам.", "Stored only on this PC. Not shared with other computers."),
        ["Пути заблокированы, пока синхронизация включена. Сначала выключите её на вкладке «Состояние»."] = ("Шляхи заблоковані, доки синхронізацію увімкнено. Спочатку вимкніть її на вкладці «Стан».", "Paths are locked while synchronization is enabled. Disable it on the Status tab first."),
        ["Для нового ПК можно выбрать НЕСУЩЕСТВУЮЩИЙ KDBX через «Новый путь…». При смене каталога данные копируются с проверкой; старый каталог сохраняется."] = ("Для нового ПК можна вибрати НЕІСНУЮЧУ KDBX через «Новий шлях…». Під час зміни каталогу дані копіюються з перевіркою; старий каталог зберігається.", "On a new PC, you can select a NONEXISTENT KDBX using “New path…”. When the folder changes, data is copied and verified; the old folder is preserved."),
        ["Язык и тема интерфейса в верхней панели — тоже локальные настройки. Реквизиты облаков хранятся только на этом ПК."] = ("Мова й тема у верхній панелі — також локальні налаштування. Облікові дані хмар зберігаються лише на цьому ПК.", "Language and theme in the top bar are local settings too. Cloud credentials are stored only on this PC."),
        ["Публикуются в topology.json и автоматически применяются на остальных компьютерах после получения обновления."] = ("Публікуються в topology.json та автоматично застосовуються на інших комп’ютерах після отримання оновлення.", "Published in topology.json and automatically applied on other computers when an update arrives."),
        ["Интервал опроса, тайм-аут и параметры кэша каждого облака — общие для всех ПК и изменяются на вкладке «Облака»."] = ("Інтервал опитування, тайм-аут і параметри кешу кожної хмари спільні для всіх ПК та змінюються на вкладці «Хмари».", "Each cloud’s polling interval, timeout and cache settings are shared across PCs and edited on the Clouds tab."),
        ["Список компьютеров, список облаков и интервалы их опроса — также общие. Изменяются во вкладках «Компьютеры» и «Облака»."] = ("Списки комп’ютерів і хмар та інтервали опитування також спільні. Редагуються на вкладках «Комп’ютери» та «Хмари».", "Computer and cloud lists and their polling intervals are shared too. Edit them on the Computers and Clouds tabs."),
        ["Общие настройки становятся доступны остальным ПК после публикации топологии; при отсутствии сети изменение останется ожидающим."] = ("Спільні налаштування стають доступними іншим ПК після публікації топології; без мережі зміна залишиться в очікуванні.", "Shared settings reach other PCs after the topology is published; while offline, the change remains pending."),
        ["В топологии: облаков — "] = ("У топології: хмар — ", "In topology: clouds — "),
        [", активных компьютеров — "] = (", активних комп’ютерів — ", ", active computers — "),
        [": опрос каждые "] = (": опитування кожні ", ": polling every "),
        ["Сначала настройте KeyPassXC Cloud Sync"] = ("Спочатку налаштуйте KeyPassXC Cloud Sync", "Set up KeyPassXC Cloud Sync first"),
        ["Сохраните путь к KDBX, каталог данных и хотя бы одно облако."] = ("Збережіть шлях до KDBX, каталог даних і хоча б одну хмару.", "Save the KDBX path, data folder and at least one cloud connection."),
        ["Опасная операция — остановка синхронизации"] = ("Небезпечна дія — зупинка синхронізації", "Dangerous operation — stop synchronization"),
        ["ОСТАНОВИТЬ синхронизацию только на этом компьютере?\n\nПосле остановки изменения KDBX не передаются в облака и не загружаются оттуда. Обмен топологией и статистикой продолжится, другие ПК продолжат работу. Версии KDBX могут разойтись.\n\nПеред повторным включением потребуется новая проверка конфликтов."] = ("ЗУПИНИТИ синхронізацію лише на цьому комп’ютері?\n\nПісля зупинки зміни KDBX не передаватимуться до хмар і не завантажуватимуться звідти. Обмін топологією та статистикою триватиме, інші ПК продовжать роботу. Версії KDBX можуть розійтися.\n\nПеред повторним увімкненням буде потрібна нова перевірка конфліктів.", "STOP synchronization only on this computer?\n\nAfter stopping, KDBX changes will neither be uploaded nor downloaded. Topology and statistics exchange will continue, and other PCs will keep working. KDBX versions may diverge.\n\nA new conflict check is required before re-enabling."),
        ["Остановить синхронизацию"] = ("Зупинити синхронізацію", "Stop synchronization"),
        ["KDBX на паузе; обмен топологией и статистикой продолжается."] = ("KDBX на паузі; обмін топологією та статистикою триває.", "KDBX paused; topology and statistics exchange continues."),
        ["Несохранённые пути"] = ("Незбережені шляхи", "Unsaved paths"),
        ["Сначала сохраните изменённые пути KDBX и каталога данных."] = ("Спочатку збережіть змінені шляхи до KDBX і каталогу даних.", "Save the changed KDBX and data-folder paths first."),
        ["Проверка облаков перед включением…"] = ("Перевірка хмар перед увімкненням…", "Checking clouds before enabling…"),
        ["Включение запрещено: проверка неполная"] = ("Увімкнення заборонено: перевірка неповна", "Cannot enable: check incomplete"),
        ["КОНФЛИКТ БУДЕТ — подтвердите запуск"] = ("БУДЕ КОНФЛІКТ — підтвердьте запуск", "CONFLICT EXPECTED — confirm start"),
        ["ЧАСТИЧНАЯ СИНХРОНИЗАЦИЯ — подтвердите запуск"] = ("ЧАСТКОВА СИНХРОНІЗАЦІЯ — підтвердьте запуск", "PARTIAL SYNCHRONIZATION — confirm start"),
        ["Синхронизация включена частично. Недоступные облака будут проверяться повторно."] = ("Синхронізацію увімкнено частково. Недоступні хмари перевірятимуться повторно.", "Synchronization enabled partially. Unavailable clouds will be retried."),
        ["КОНФЛИКТА НЕ ОБНАРУЖЕНО — подтвердите запуск"] = ("КОНФЛІКТІВ НЕ ВИЯВЛЕНО — підтвердьте запуск", "NO CONFLICT FOUND — confirm start"),
        ["ВНИМАНИЕ: конфликтующие версии будут сохранены отдельно; автоматического объединения и перезаписи не будет.\n\n"] = ("УВАГА: конфліктні версії будуть збережені окремо; автоматичного об’єднання чи перезапису не буде.\n\n", "WARNING: conflicting versions will be saved separately; there will be no automatic merge or overwrite.\n\n"),
        ["Включить синхронизацию на этом компьютере?"] = ("Увімкнути синхронізацію на цьому комп’ютері?", "Enable synchronization on this computer?"),
        ["Переключатель изменён в другом процессе."] = ("Перемикач змінено в іншому процесі.", "The switch was changed in another process."),
        ["Настройки облаков изменились во время подтверждения. Повторите проверку."] = ("Налаштування хмар змінилися під час підтвердження. Повторіть перевірку.", "Cloud settings changed during confirmation. Run the check again."),
        ["Состояние KDBX или облаков изменилось после первого анализа. Включение отменено — повторите проверку и подтверждение.\n\n"] = ("Стан KDBX або хмар змінився після першого аналізу. Увімкнення скасовано — повторіть перевірку й підтвердження.\n\n", "KDBX or cloud state changed after the first check. Enabling was cancelled — repeat the check and confirmation.\n\n"),
        ["Синхронизация включена после двух успешных сверок."] = ("Синхронізацію увімкнено після двох успішних перевірок.", "Synchronization enabled after two successful checks."),
        ["Изменение синхронизации не выполнено"] = ("Не вдалося змінити стан синхронізації", "Could not change synchronization state"),
        ["Укажите путь к будущей KDBX (создавать её не нужно)"] = ("Укажіть шлях до майбутньої KDBX (створювати її не потрібно)", "Specify the future KDBX path (do not create the file)"),
        ["Путь новой KDBX"] = ("Шлях до нової KDBX", "New KDBX path"),
        ["Путь KDBX и каталог данных можно менять только при выключенной синхронизации."] = ("Шлях KDBX і каталог даних можна змінювати лише за вимкненої синхронізації.", "KDBX and data-folder paths can only be changed when synchronization is disabled."),
        ["Настройки сохранены. Цикл синхронизации возобновлён."] = ("Налаштування збережено. Цикл синхронізації відновлено.", "Settings saved. Synchronization cycle resumed."),
        ["Настройки сохранены. Синхронизация выключена — сначала выполните проверку и включение."] = ("Налаштування збережено. Синхронізацію вимкнено — спочатку виконайте перевірку й увімкнення.", "Settings saved. Synchronization is disabled — run the checks and enable it first."),
        ["Этот компьютер отключён от синхронизации"] = ("Цей комп’ютер від’єднано від синхронізації", "This computer is disconnected from synchronization"),
