    // A translated label followed by runtime data (date, path, count or interval)
    // must not fall back to Russian merely because its complete value is absent
    // from Terms. Derive these prefixes from the same catalog so new labels
    // Trailing fragments in labels are handled by the same translation logic.
    private static readonly (string Ru,string Uk,string En)[] ValuePrefixes = Terms
        .Where(item=>item.Key.EndsWith(": ",StringComparison.Ordinal)
            || item.Key.EndsWith("каждые ",StringComparison.Ordinal))
        .OrderByDescending(item=>item.Key.Length)
        .Select(item=>(Ru:item.Key,Uk:item.Value.Uk,En:item.Value.En))
        .ToArray();

    // The canonical stored automatic-theme value is distinct from its display label.
    // The displayed automatic-theme label is consistent across UI languages.
    internal static string ThemeName(string storedValue) =>
        storedValue == "Системная" ? T("Авто") : T(storedValue);

    internal static string Selected { get; private set; } = "auto";
    internal static string Active => Selected == "auto" ? SystemLanguage() : Selected;
    internal static void Use(string selected) => Selected = selected is "ru" or "uk" or "en" ? selected : "auto";
    private static string SystemLanguage() => CultureInfo.CurrentUICulture.TwoLetterISOLanguageName switch
    {
        "ru" => "ru", "uk" => "uk", _ => "en"
    };
    internal static string T(string? source)
    {
        if(string.IsNullOrEmpty(source) || Active=="ru")return source??"";
        var lang=Active;
        if(Terms.TryGetValue(source,out var word))return lang=="uk"?word.Uk:word.En;
        // Preserve dynamic values, such as filenames, versions and account names.
        foreach(var p in DynamicPrefixes)
            if(source.StartsWith(p.Ru,StringComparison.Ordinal))
            {
                var tail=source[p.Ru.Length..];
                return (lang=="uk"?p.Uk:p.En)+T(tail);
            }
        // Prefer the longest known localized label before preserving the
        // trailing dynamic value. Explicit DynamicPrefixes above still handle
        // special cases such as account names and punctuation.
        foreach(var p in ValuePrefixes)
            if(source.Length>p.Ru.Length && source.StartsWith(p.Ru,StringComparison.Ordinal))
                return (lang=="uk"?p.Uk:p.En)+T(source[p.Ru.Length..]);
        if(source.Contains(" · ",StringComparison.Ordinal))
            return string.Join(" · ",source.Split(" · ").Select(T));
        if(source.Contains('\n'))return string.Join("\n",source.Split('\n').Select(T));
        return source;
    }
